import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.DSg0KOwT.js";const p=JSON.parse('{"title":"Memory Utilization","titleTemplate":":title | Spark Tuning Reference","description":"Detecting and mitigating executor memory that is poorly used: peak heap above 95% (raise memory) or below 70% (over-provisioned) of spark.executor.memory, idle cores in held executors and the dynamic-allocation idle timeouts that reclaim them, and the low-confidence allocated-vs-used waste estimate.","frontmatter":{"title":"Memory Utilization","titleTemplate":":title | Spark Tuning Reference","description":"Detecting and mitigating executor memory that is poorly used: peak heap above 95% (raise memory) or below 70% (over-provisioned) of spark.executor.memory, idle cores in held executors and the dynamic-allocation idle timeouts that reclaim them, and the low-confidence allocated-vs-used waste estimate."},"headers":[],"relativePath":"tuning-reference/bottleneck-memory-utilization.md","filePath":"tuning-reference/bottleneck-memory-utilization.md"}'),s={name:"tuning-reference/bottleneck-memory-utilization.md"};function n(i,e,c,l,f,h){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="bottleneck-memory-utilization" tabindex="-1">Memory Utilization <a class="header-anchor" href="#bottleneck-memory-utilization" aria-label="Permalink to &quot;Memory Utilization {#bottleneck-memory-utilization}&quot;">​</a></h1><p><span class="tag">MEM</span></p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>An executor&#39;s memory is a fixed allocation. <code>spark.executor.memory</code> sets the amount of memory per executor process, which is its JVM heap<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>. On YARN and Kubernetes the container or pod also carries <code>spark.executor.memoryOverhead</code> on top, plus any off-heap and PySpark memory<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup>. The executor holds the whole allocation for its entire lifetime, whether or not it has work to run<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>. This finding checks how well that allocation is used, from three angles: how close each executor&#39;s heap came to its limit, how much allocated memory-time went unused over the run, and how many cores sat idle in held executors.</p><p>The heap check reads Spark&#39;s peak heap metric. Executor metrics are sent from each executor to the driver with its heartbeat, and the per-executor peak of <code>JVMHeapMemory</code> is the highest used heap the executor reported. &quot;Used&quot; there counts &quot;the amount of memory occupied by both live objects and garbage objects that have not been collected&quot;<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup>. The finding compares that peak with <code>spark.executor.memory</code>. The metric reaches the event log only when <code>spark.eventLog.logStageExecutorMetrics</code> is true<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3:1]</a></sup>.</p><p>The core check is about concurrency. An executor&#39;s core count is its concurrency ceiling: <code>--executor-cores 5</code> caps it at five concurrent tasks<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup>. The scheduler turns cores into task slots from <code>spark.executor.cores</code> and <code>spark.task.cpus</code>, which defaults to one core per task<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1:2]</a></sup>. Cores go idle whenever there are fewer runnable tasks than slots: a stage with fewer partitions than total slots leaves slots empty, and so does the tail of a stage where a <a href="./bottleneck-straggler.html">straggler</a> or two keep running after their peers finish. Through all of it the JVM keeps its fixed heap<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2:1]</a></sup>.</p><h2 id="how-it-s-detected" tabindex="-1">How it&#39;s detected <a class="header-anchor" href="#how-it-s-detected" aria-label="Permalink to &quot;How it&#39;s detected&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Fires when</th><th>Status</th></tr></thead><tbody><tr><td>heapNearCapacity</td><td>An executor&#39;s peak heap is above 95% of <code>spark.executor.memory</code> (memory may be too small)</td><td>Validated</td></tr><tr><td>heapOverProvisioned</td><td>An executor&#39;s peak heap is below 70% of <code>spark.executor.memory</code> (memory may be over-provisioned, a cost signal)</td><td>Validated</td></tr><tr><td>idleCores</td><td>More than 50% of the available core-time ran no task</td><td>Validated</td></tr><tr><td>wasteModel</td><td>Allocated memory-time exceeds used memory-time by more than 2.5 times (wasted memory-time, allocated minus used, above 1.5 times used)</td><td>Experimental</td></tr></tbody></table><p>Both heap rules look at executors one at a time, so a run can produce one finding per executor. Driver memory is not evaluated. If the log carries no per-executor memory metrics, the heap rules cannot run, and the finding says so and points at <code>spark.eventLog.logStageExecutorMetrics</code> instead.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>The two heap bands are opposite problems.</p><p>A heap near its limit leaves tasks little room. When a sort or hash-aggregation operator keeps asking for execution memory it cannot get, Spark blocks the task, spills its in-memory data to disk, or in the worst case throws an <code>OutOfMemoryError</code><sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2:2]</a></sup>. A full GC invoked several times before a task completes means there isn&#39;t enough memory for executing tasks<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup>.</p><p>A heap far below its limit is the opposite: allocation you pay for without using it. On YARN that is the memory YARN grants the container; on Kubernetes it is the pod memory limit<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2:3]</a></sup>. Idle cores and lingering executors cost the same way, since the fixed band is reserved whether or not tasks are running.</p><h2 id="how-to-fix-it" tabindex="-1">How to fix it <a class="header-anchor" href="#how-to-fix-it" aria-label="Permalink to &quot;How to fix it&quot;">​</a></h2><h3 id="heap-near-capacity" tabindex="-1">Heap near capacity <a class="header-anchor" href="#heap-near-capacity" aria-label="Permalink to &quot;Heap near capacity&quot;">​</a></h3><p>Check first whether the pressure is real. The peak counts uncollected garbage, so a high reading alone does not prove a shortage<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3:2]</a></sup>. Look at <a href="./bottleneck-spill.html">spill</a> and <a href="./bottleneck-gc.html">GC pressure</a> for the same executor and stages. Spill, or heavy GC with repeated full collections, points at a real shortage<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5:1]</a></sup>.</p><p>If it is real, there are three levers:</p><ul><li>Raise <code>spark.executor.memory</code>. The container request is the sum of <code>spark.executor.memoryOverhead</code>, <code>spark.executor.memory</code>, <code>spark.memory.offHeap.size</code> and <code>spark.executor.pyspark.memory</code>, so the cluster must have room for the larger total<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1:3]</a></sup>.</li><li>Shrink what each task holds. When the working set of a task is too large, such as a reduce task building a hash table, the simplest fix is to raise the level of parallelism so each task&#39;s input set is smaller<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5:2]</a></sup>.</li><li>Run fewer tasks per executor. Each task may take roughly between <code>1/(2n)</code> and <code>1/n</code> of execution memory with <code>n</code> tasks running, so lowering <code>spark.executor.cores</code> raises each task&#39;s share<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2:4]</a></sup>.</li></ul><p>A heap finding does not cover memory outside the heap. A container killed for exceeding its memory limit shows up as a container-memory error rather than a Spark exception, and the fix there is overhead sizing, covered on the <a href="./memory-model.html">memory management</a> page<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2:5]</a></sup>.</p><h3 id="heap-over-provisioned" tabindex="-1">Heap over-provisioned <a class="header-anchor" href="#heap-over-provisioned" aria-label="Permalink to &quot;Heap over-provisioned&quot;">​</a></h3><p>Lower <code>spark.executor.memory</code> toward the observed peak, in steps, and re-check spill and GC after each change. The unified execution and storage region is a fraction of the heap (<code>spark.memory.fraction</code> of the heap minus 300 MiB), so a smaller heap shrinks it in proportion<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5:3]</a></sup>. Because per-task execution memory shrinks with it, a heap cut too far trades the cost signal for spill<sup class="footnote-ref"><a href="#fn2" id="fnref2:6">[2:6]</a></sup>. Cached data lives in that region too, so a job that persists large datasets needs the headroom its <a href="./caching.html">cache</a> will use.</p><h3 id="idle-cores-and-held-executors" tabindex="-1">Idle cores and held executors <a class="header-anchor" href="#idle-cores-and-held-executors" aria-label="Permalink to &quot;Idle cores and held executors&quot;">​</a></h3><p>Keep executors from being oversized in the first place. Assigning all 16 cores of a node to a single executor hurts HDFS throughput and drives excessive <a href="./bottleneck-gc.html">garbage collection</a>, so aim for a balance between tiny (one core per executor) and fat (one executor per node) sizing<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup>. On YARN, leave cores for the OS and Hadoop daemons instead of handing 100% of a node to Spark containers<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4:1]</a></sup>.</p><p>For the held memory band, lean on <a href="./cluster-config.html">dynamic allocation</a> to reclaim executors once the work drains. It requests executors when tasks back up and frees them when they go idle<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4:2]</a></sup>. Executors are added in rounds once tasks have been pending for <code>spark.dynamicAllocation.schedulerBacklogTimeout</code> (default 1s), then again every <code>spark.dynamicAllocation.sustainedSchedulerBacklogTimeout</code> while the backlog holds<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup>. On the release side, an executor is removed after it has been idle longer than <code>spark.dynamicAllocation.executorIdleTimeout</code><sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7:1]</a></sup>.</p><p>Cached data is the trap here. By default an executor holding <a href="./caching.html">cached blocks</a> is never removed, governed by <code>spark.dynamicAllocation.cachedExecutorIdleTimeout</code>, whose default is infinity<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1:4]</a></sup>. Such an executor keeps its full memory band indefinitely with no active tasks unless you set that timeout to a finite value, or turn on <code>spark.shuffle.service.fetch.rdd.enabled</code> so executors holding only disk-persisted blocks are treated as idle after <code>spark.dynamicAllocation.executorIdleTimeout</code> and released<sup class="footnote-ref"><a href="#fn7" id="fnref7:2">[7:2]</a></sup>. To avoid holding barely-used executors at all, lower <code>spark.dynamicAllocation.executorAllocationRatio</code> (default 1.0, full parallelism) toward 0.5, since with small tasks full-parallelism allocation can request executors that never do any work<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1:5]</a></sup>.</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Balanced executor sizing, not one fat executor per node</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.executor.cores</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reclaim idle executors; give cached holders a finite timeout</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.dynamicAllocation.enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.dynamicAllocation.cachedExecutorIdleTimeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=300s</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.dynamicAllocation.executorAllocationRatio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0.5</span></span></code></pre></div><h3 id="reading-the-wasted-memory-estimate-experimental" tabindex="-1">Reading the wasted-memory estimate <span class="tag">EXPERIMENTAL</span> <a class="header-anchor" href="#reading-the-wasted-memory-estimate-experimental" aria-label="Permalink to &quot;Reading the wasted-memory estimate &lt;span class=&quot;tag&quot;&gt;EXPERIMENTAL&lt;/span&gt;&quot;">​</a></h3><p>The wasteModel rule compares two memory-time figures. Allocated memory-time is the executor memory multiplied by the number of executors and the run duration. Used memory-time approximates the allocation as in use for as long as tasks ran, taking executor memory multiplied by the total task run time. The rule fires when that difference, the wasted memory-time, exceeds 1.5 times the used figure, which means allocated memory-time is more than 2.5 times used. Treat it as a rough buffer heuristic, not a measurement. It prices time with no task running, not bytes of heap left empty, so it can disagree with the heap bands: an executor can be busy all run with a half-empty heap, or idle with a full one. Use the number as a hint that the cluster may be oversized or underused, then confirm against sizing before acting on it.</p><h2 id="confidence" tabindex="-1">Confidence <a class="header-anchor" href="#confidence" aria-label="Permalink to &quot;Confidence&quot;">​</a></h2><p>The idleCores rule and both heap rules are validated: they rest on documented Spark concurrency, dynamic-allocation and heap-metric behavior. The wasteModel estimate is low-confidence and experimental. It is a buffer heuristic derived from allocated-versus-run-time accounting, not an exact measure of unused memory, so it should steer investigation rather than settle it.</p><h2 id="limitations-false-positive-risk" tabindex="-1">Limitations / false-positive risk <a class="header-anchor" href="#limitations-false-positive-risk" aria-label="Permalink to &quot;Limitations / false-positive risk&quot;">​</a></h2><p>The heap peak counts garbage the JVM has not collected yet<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3:3]</a></sup>, so heapNearCapacity can fire on an executor that never ran short of memory. Confirm with spill and GC time before raising memory. The peak is also only as fine-grained as the metric polling. With <code>spark.executor.metrics.pollingInterval</code> at its default of 0, metrics are collected on executor heartbeats, at <code>spark.executor.heartbeatInterval</code><sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1:6]</a></sup>, so a short spike between heartbeats can go unseen and heapOverProvisioned can understate real use. The heap ratio sees only the heap: overhead, off-heap and PySpark memory are outside it<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1:7]</a></sup>.</p><p>Idle cores are not always waste. The tail of a stage legitimately leaves slots empty while a straggler or two finish<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1:8]</a></sup>, so a snapshot of low parallelism can reflect a normal straggler tail rather than chronic under-utilization. Executor metrics are absent entirely unless <code>spark.eventLog.logStageExecutorMetrics</code> is enabled<sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3:4]</a></sup>.</p><blockquote><p><strong>Managed platforms:</strong> Several platforms set or replace the executor sizing and scaling this page discusses. Databricks autoscaling replaces <code>spark.dynamicAllocation.enabled</code>, and serverless compute does not support most Spark properties.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup> On Amazon EMR, <code>maximizeResourceAllocation</code> sets <code>spark.executor.memory</code> and related spark-defaults values from the instance type,<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup> and managed scaling expects Spark dynamic allocation to stay enabled.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup> AWS Glue memory is fixed by worker type, 16 GB for G.1X and 32 GB for G.2X, with one executor per worker.<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup></p></blockquote><blockquote><p><strong>Native engines:</strong> <a href="#native-gluten">Apache Gluten</a> and <a href="#native-comet">Apache DataFusion Comet</a> cover native memory sizing, which the heap ratio does not see.</p></blockquote><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://spark.apache.org/docs/latest/configuration.html" target="_blank" rel="noreferrer">Configuration — Spark</a> <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a> <a href="#fnref1:2" class="footnote-backref">↩︎</a> <a href="#fnref1:3" class="footnote-backref">↩︎</a> <a href="#fnref1:4" class="footnote-backref">↩︎</a> <a href="#fnref1:5" class="footnote-backref">↩︎</a> <a href="#fnref1:6" class="footnote-backref">↩︎</a> <a href="#fnref1:7" class="footnote-backref">↩︎</a> <a href="#fnref1:8" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p><a href="https://luminousmen.com/post/dive-into-spark-memory" target="_blank" rel="noreferrer">Dive into Spark memory</a> <a href="#fnref2" class="footnote-backref">↩︎</a> <a href="#fnref2:1" class="footnote-backref">↩︎</a> <a href="#fnref2:2" class="footnote-backref">↩︎</a> <a href="#fnref2:3" class="footnote-backref">↩︎</a> <a href="#fnref2:4" class="footnote-backref">↩︎</a> <a href="#fnref2:5" class="footnote-backref">↩︎</a> <a href="#fnref2:6" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><a href="https://spark.apache.org/docs/latest/monitoring.html" target="_blank" rel="noreferrer">Monitoring — Spark</a> <a href="#fnref3" class="footnote-backref">↩︎</a> <a href="#fnref3:1" class="footnote-backref">↩︎</a> <a href="#fnref3:2" class="footnote-backref">↩︎</a> <a href="#fnref3:3" class="footnote-backref">↩︎</a> <a href="#fnref3:4" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><a href="https://blog.cloudera.com/how-to-tune-your-apache-spark-jobs-part-2/" target="_blank" rel="noreferrer">How to Tune Your Apache Spark Jobs (Part 2)</a> <a href="#fnref4" class="footnote-backref">↩︎</a> <a href="#fnref4:1" class="footnote-backref">↩︎</a> <a href="#fnref4:2" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p><a href="https://spark.apache.org/docs/latest/tuning.html" target="_blank" rel="noreferrer">Tuning Spark</a> <a href="#fnref5" class="footnote-backref">↩︎</a> <a href="#fnref5:1" class="footnote-backref">↩︎</a> <a href="#fnref5:2" class="footnote-backref">↩︎</a> <a href="#fnref5:3" class="footnote-backref">↩︎</a></p></li><li id="fn6" class="footnote-item"><p><a href="https://raw.githubusercontent.com/spoddutur/spark-notes/master/distribution_of_executors_cores_and_memory_for_spark_application.md" target="_blank" rel="noreferrer">Distribution of executors, cores and memory for a Spark application</a> <a href="#fnref6" class="footnote-backref">↩︎</a></p></li><li id="fn7" class="footnote-item"><p><a href="https://spark.apache.org/docs/latest/job-scheduling.html" target="_blank" rel="noreferrer">Job Scheduling — Spark</a> <a href="#fnref7" class="footnote-backref">↩︎</a> <a href="#fnref7:1" class="footnote-backref">↩︎</a> <a href="#fnref7:2" class="footnote-backref">↩︎</a></p></li><li id="fn8" class="footnote-item"><p><a href="https://docs.databricks.com/aws/en/spark/conf" target="_blank" rel="noreferrer">Set Spark configuration properties on Databricks</a> <a href="#fnref8" class="footnote-backref">↩︎</a></p></li><li id="fn9" class="footnote-item"><p><a href="https://docs.aws.amazon.com/emr/latest/ReleaseGuide/emr-spark-configure.html" target="_blank" rel="noreferrer">Configure Spark — Amazon EMR</a> <a href="#fnref9" class="footnote-backref">↩︎</a></p></li><li id="fn10" class="footnote-item"><p><a href="https://docs.aws.amazon.com/emr/latest/ManagementGuide/emr-managed-scaling.html" target="_blank" rel="noreferrer">Using managed scaling in Amazon EMR</a> <a href="#fnref10" class="footnote-backref">↩︎</a></p></li><li id="fn11" class="footnote-item"><p><a href="https://docs.aws.amazon.com/glue/latest/dg/add-job.html" target="_blank" rel="noreferrer">Adding jobs in AWS Glue</a> <a href="#fnref11" class="footnote-backref">↩︎</a></p></li></ol></section>`,37)])])}const u=a(s,[["render",n]]);export{p as __pageData,u as default};
